create table if not exists public.aurora_assisted_courses (id text primary key,created_by uuid not null references auth.users(id) on delete cascade,title text not null default 'Nouveau cours',status text not null default 'draft' check(status in ('draft','editing','preview','validated','generating','completed','error')),course_json jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index if not exists idx_aurora_assisted_courses_created_by on public.aurora_assisted_courses(created_by);create index if not exists idx_aurora_assisted_courses_updated_at on public.aurora_assisted_courses(updated_at desc);alter table public.aurora_assisted_courses enable row level security;drop policy if exists "aurora_assisted_courses_admin_select" on public.aurora_assisted_courses;create policy "aurora_assisted_courses_admin_select" on public.aurora_assisted_courses for select to authenticated using(exists(select 1 from public."Profils" p where p.id=auth.uid() and p.role='admin' and coalesce(p.banni,false)=false));drop policy if exists "aurora_assisted_courses_admin_insert" on public.aurora_assisted_courses;create policy "aurora_assisted_courses_admin_insert" on public.aurora_assisted_courses for insert to authenticated with check(created_by=auth.uid() and exists(select 1 from public."Profils" p where p.id=auth.uid() and p.role='admin' and coalesce(p.banni,false)=false));drop policy if exists "aurora_assisted_courses_admin_update" on public.aurora_assisted_courses;create policy "aurora_assisted_courses_admin_update" on public.aurora_assisted_courses for update to authenticated using(exists(select 1 from public."Profils" p where p.id=auth.uid() and p.role='admin' and coalesce(p.banni,false)=false)) with check(created_by=auth.uid() and exists(select 1 from public."Profils" p where p.id=auth.uid() and p.role='admin' and coalesce(p.banni,false)=false));drop policy if exists "aurora_assisted_courses_admin_delete" on public.aurora_assisted_courses;create policy "aurora_assisted_courses_admin_delete" on public.aurora_assisted_courses for delete to authenticated using(exists(select 1 from public."Profils" p where p.id=auth.uid() and p.role='admin' and coalesce(p.banni,false)=false));